const $=id=>document.getElementById(id);let db,state,currentView='overview',selected=[],activeDoc,previewUrl;
const sample=()=>({cases:[{id:'S001',label:'Sample case 001',service:'IIC'},{id:'S002',label:'Sample case 002',service:'Behavioral Assistance'},{id:'S003',label:'Sample case 003',service:'BPS Assessment'}],docs:[{id:'D001',caseId:'S001',title:'Sample intake form',type:'Intake form',date:'2026-10-10',notes:'Fictional example. Attach a blank form to try capture.',status:'Needs review',events:['Sample document created']},{id:'D002',caseId:'S002',title:'Sample consent checklist',type:'Consent form',date:'2026-10-10',notes:'Fictional example record.',status:'Approved',events:['Sample document created','Sample approval recorded']}],tasks:[{id:'T001',caseId:'S001',title:'Review sample intake',due:'2026-10-12',done:false}]});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const uid=()=>crypto.randomUUID();const today=()=>new Date().toLocaleDateString('en-CA');
function toast(msg){$('toast').textContent=msg;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',3500)}
function transaction(store,mode,fn){return new Promise((resolve,reject)=>{const tx=db.transaction(store,mode),req=fn(tx.objectStore(store));tx.oncomplete=()=>resolve(req.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
let committedWorkspace=null,workspaceSaving=false;
async function persist(){
 const snapshot=structuredClone(state);workspaceSaving=true;
 try{await transaction('workspace','readwrite',s=>s.put(snapshot,'state'));committedWorkspace=snapshot;render()}
 catch(cause){if(committedWorkspace){state=structuredClone(committedWorkspace);if(activeDoc)activeDoc=state.docs.find(d=>d.id===activeDoc.id);if(typeof reviewingIntake!=='undefined'&&reviewingIntake)reviewingIntake=state.intakes.find(i=>i.id===reviewingIntake.id);render()}const error=new Error('Could not save changes. Check browser storage and retry.');error.name='WorkspaceSaveError';error.cause=cause;throw error}
 finally{workspaceSaving=false}
}
for(const kind of ['click','submit','change'])document.addEventListener(kind,event=>{if(workspaceSaving&&event.target.closest('button,form,input,select')){event.preventDefault();event.stopImmediatePropagation();toast('Finishing the previous save. Please try again in a moment.')}},true);
window.addEventListener('unhandledrejection',event=>{if(event.reason?.name==='WorkspaceSaveError'){event.preventDefault();toast(event.reason.message)}});
function caseOptions(){return state.cases.map(c=>`<option value="${esc(c.id)}">${esc(c.label)} · ${esc(c.service)}</option>`).join('')}
function matching(c){const q=$('search').value.toLowerCase(),service=$('service-filter').value;return (!service||c.service===service)&&(!q||c.label.toLowerCase().includes(q)||c.service.toLowerCase().includes(q))}
function docRow(d){const c=state.cases.find(c=>c.id===d.caseId);return `<div class="case-row"><span class="case-icon">▧</span><div class="row-info"><strong>${esc(d.title)}</strong><small>${esc(c?.label)} · ${esc(d.type)} · ${esc(d.date)}</small></div><span class="badge ${d.status==='Approved'?'approved':''}">${esc(d.status)}</span><button class="row-button" data-doc="${esc(d.id)}">Open ↗</button></div>`}
function render(){const n=state.docs.filter(d=>d.status==='Needs review').length;$('case-count').textContent=state.cases.length;$('review-count').textContent=n;$('nav-count').textContent=n;$('approved-count').textContent=state.docs.length-n;$('page-title').textContent=({overview:'Overview',cases:'Case folders',review:'Review queue',tasks:'Follow-up tasks'})[currentView];$('list-title').textContent=({overview:'Your document workspace',cases:'Case folders',review:'Documents needing review',tasks:'Follow-up tasks'})[currentView];$('list-subtitle').textContent=currentView==='tasks'?'Track the next step for each case.':'Search, organize, and review your sample records.';document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===currentView));const q=$('search').value.toLowerCase(),sf=$('service-filter').value;let html='';if(currentView==='cases'){html=state.cases.filter(matching).map(c=>{const docs=state.docs.filter(d=>d.caseId===c.id);return `<div class="case-row"><span class="case-icon">▤</span><div class="row-info"><strong>${esc(c.label)}</strong><small>${esc(c.service)} · ${docs.length} documents · ${docs.filter(d=>d.status==='Needs review').length} awaiting review</small></div><button class="row-button" data-capture-case="${esc(c.id)}">＋ Add</button></div>`}).join('')}else if(currentView==='tasks'){html=state.tasks.filter(t=>{const c=state.cases.find(c=>c.id===t.caseId);return c&&(!sf||c.service===sf)&&(!q||`${t.title} ${c.label}`.toLowerCase().includes(q))}).map(t=>`<div class="case-row"><input type="checkbox" aria-label="Complete ${esc(t.title)}" data-task="${esc(t.id)}" ${t.done?'checked':''} style="width:18px"><div class="row-info"><strong>${esc(t.title)}</strong><small>${esc(state.cases.find(c=>c.id===t.caseId)?.label)} · Due ${esc(t.due)}</small></div><span class="badge ${t.done?'approved':''}">${t.done?'Done':'Open'}</span></div>`).join('')}else{html=state.docs.filter(d=>{const c=state.cases.find(c=>c.id===d.caseId);return c&&(!sf||c.service===sf)&&(currentView!=='review'||d.status==='Needs review')&&(!q||`${d.title} ${d.notes} ${c.label} ${d.type}`.toLowerCase().includes(q))}).map(docRow).join('')}$('records').innerHTML=html||'<div class="empty">No matching records. Create a case or capture a sample document to get started.</div>'}
function openCapture(caseId){selected=[];$('capture-form').reset();$('capture-case').innerHTML=caseOptions();if(caseId)$('capture-case').value=caseId;$('doc-date').value=today();$('selected-files').textContent='No documents selected.';$('capture').showModal()}
async function chooseFiles(files){const accepted=[];for(const f of files){if(!['image/png','image/jpeg','application/pdf'].includes(f.type)){toast('Choose a PNG, JPEG or PDF file.');continue}if(f.size<=0||f.size>15*1024*1024){toast('Each file must be 15 MB or smaller.');continue}accepted.push(f)}selected.push(...accepted);$('selected-files').textContent=selected.length?selected.map(f=>`${f.name} (${(f.size/1024/1024).toFixed(1)} MB)`).join(' · '):'No documents selected.'}
async function openDoc(id){activeDoc=state.docs.find(d=>d.id===id);const d=activeDoc;$('detail-title').textContent=d.title;$('review-title').value=d.title;$('review-case').innerHTML=caseOptions();$('review-case').value=d.caseId;$('review-type').value=d.type;$('review-date').value=d.date;$('review-notes').value=d.notes;$('confirm-review').checked=false;$('approve-doc').disabled=d.status==='Approved';$('approve-doc').textContent=d.status==='Approved'?'Approved':'Approve document';$('history').textContent=(d.events||[]).join(' • ');if(previewUrl)URL.revokeObjectURL(previewUrl);$('document-preview').replaceChildren();if(d.blob){previewUrl=URL.createObjectURL(d.blob);if(d.blob.type.startsWith('image/')){const img=document.createElement('img');img.src=previewUrl;img.alt='Uploaded document';img.className='preview-image';$('document-preview').append(img)}else{const a=document.createElement('a');a.href=previewUrl;a.target='_blank';a.rel='noopener';a.textContent='Open original PDF ↗';a.className='pdf-link';$('document-preview').append(a)}}else{$('document-preview').innerHTML='<div class="sample-preview">Fictional sample record · No source file attached</div>'}$('detail').showModal()}
function updateReview(){if(!$('review-form').reportValidity())return false;const changed=activeDoc.title!==$('review-title').value.trim()||activeDoc.caseId!==$('review-case').value||activeDoc.type!==$('review-type').value||activeDoc.date!==$('review-date').value||activeDoc.notes!==$('review-notes').value;activeDoc.title=$('review-title').value.trim();activeDoc.caseId=$('review-case').value;activeDoc.type=$('review-type').value;activeDoc.date=$('review-date').value;activeDoc.notes=$('review-notes').value;if(changed)activeDoc.status='Needs review';return true}
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{currentView=b.dataset.view;render()});$('search').oninput=render;$('service-filter').onchange=render;$('capture-open').onclick=()=>openCapture();$('new-case').onclick=()=>{$('case-form').reset();$('case-modal').showModal()};$('camera').onchange=e=>chooseFiles(e.target.files);$('files').onchange=e=>chooseFiles(e.target.files);
$('capture-form').onsubmit=async e=>{e.preventDefault();if(!selected.length){toast('Take a photo or choose a file first.');return}const button=e.submitter;button.disabled=true;const added=selected.map(f=>({id:uid(),caseId:$('capture-case').value,title:f.name,type:$('doc-type').value,date:$('doc-date').value,notes:$('doc-notes').value,status:'Needs review',blob:f,events:[`Uploaded ${new Date().toLocaleString()}`]}));state.docs.push(...added);try{await persist();$('capture').close();currentView='review';render();toast('Documents saved to the review queue.')}catch(err){state.docs=state.docs.filter(d=>!added.includes(d));toast('Could not save files. Browser storage may be full.')}finally{button.disabled=false}};
$('case-form').onsubmit=async e=>{e.preventDefault();const label=$('case-label').value.trim();if(!label)return;state.cases.push({id:uid(),label,service:$('case-service').value});await persist();$('case-modal').close();currentView='cases';render();toast('Case folder created.')};$('records').onclick=e=>{const d=e.target.closest('[data-doc]'),c=e.target.closest('[data-capture-case]');if(d)openDoc(d.dataset.doc);if(c)openCapture(c.dataset.captureCase)};$('records').onchange=async e=>{if(e.target.dataset.task){state.tasks.find(t=>t.id===e.target.dataset.task).done=e.target.checked;await persist()}};
$('review-form').onsubmit=async e=>{e.preventDefault();if(!updateReview())return;activeDoc.events.push(`Details saved ${new Date().toLocaleString()}`);await persist();$('detail').close();toast('Changes saved. Edited documents return to review.')};$('approve-doc').onclick=async()=>{if(!$('confirm-review').checked){toast('Confirm you checked the document details first.');return}if(!updateReview())return;activeDoc.status='Approved';activeDoc.events.push(`Approved in prototype ${new Date().toLocaleString()}`);await persist();$('detail').close();toast('Document approved.')};$('delete-doc').onclick=async()=>{if(!confirm('Delete this sample document from this browser?'))return;state.docs=state.docs.filter(d=>d.id!==activeDoc.id);await persist();$('detail').close();toast('Document deleted.')};$('reset').onclick=async()=>{if(!confirm('Remove your sample files and restore the fictional starter records?'))return;state=sample();await persist();toast('Sample workspace reset.')};
const taskNav=document.createElement('button');taskNav.dataset.view='tasks';taskNav.textContent='☑  Follow-up tasks';taskNav.onclick=()=>{currentView='tasks';render()};document.querySelector('nav').append(taskNav);
const quick=document.createElement('section');quick.className='quick-actions';quick.innerHTML='<button id="digital-open" class="secondary">▧ Write a digital form</button><button id="task-open" class="secondary">＋ Plan follow-up</button><button id="export-open" class="secondary">↧ Export records</button><span>No paper needed: capture an existing form or write a new one here.</span>';document.querySelector('.stats').after(quick);
$('task-open').onclick=()=>{$('task-form').reset();$('task-case').innerHTML=caseOptions();$('task-due').value=today();$('task-modal').showModal()};$('task-form').onsubmit=async e=>{e.preventDefault();if(!$('task-title').value.trim())return;state.tasks.push({id:uid(),caseId:$('task-case').value,title:$('task-title').value.trim(),due:$('task-due').value,done:false});await persist();$('task-modal').close();currentView='tasks';render();toast('Follow-up task saved. Notifications are not connected.')};
$('digital-open').onclick=()=>{$('digital-form').reset();$('digital-case').innerHTML=caseOptions();$('digital-date').value=today();$('digital-modal').showModal()};$('digital-form').onsubmit=async e=>{e.preventDefault();const date=$('digital-date').value;state.docs.push({id:uid(),caseId:$('digital-case').value,title:`Digital service note · ${date}`,type:'Service note',date,notes:`SESSION SUMMARY\n${$('digital-summary').value}\n\nACTIONS TAKEN\n${$('digital-actions').value}\n\nNEXT STEPS\n${$('digital-next').value}`,status:'Needs review',events:[`Digital draft created ${new Date().toLocaleString()}`]});await persist();$('digital-modal').close();currentView='review';render();toast('Digital note saved for review.')};
$('export-open').onclick=()=>{const out={exportedAt:new Date().toISOString(),prototype:true,cases:state.cases,documents:state.docs.map(({blob,...d})=>({...d,originalFileIncluded:false})),tasks:state.tasks,enrollments:state.enrollments||[]};const url=URL.createObjectURL(new Blob([JSON.stringify(out,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='eero-sample-records.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Record details exported. Original file attachments are not included.')};
async function init(){const req=indexedDB.open('eero-care-prototype',1);req.onupgradeneeded=()=>req.result.createObjectStore('workspace');db=await new Promise((res,rej)=>{req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error)});state=await transaction('workspace','readonly',s=>s.get('state'))||sample();state.tasks??=[];await persist()};init().catch(()=>{toast('Browser storage is unavailable. Enable site storage to use this prototype.');document.querySelectorAll('button').forEach(b=>b.disabled=true)});
